243	func normalizeAgentString(s string) string {
244		if s == "" {
245			return agentUnknown
246		}
247	
248		var sb strings.Builder
249		for _, r := range s {
250			if r == ' ' || r == '-' || r == '_' {
251				continue
252			}
253			if r >= 'A' && r <= 'Z' {
254				sb.WriteByte(byte(r + 32))
255			} else {
256				sb.WriteRune(r)
257			}
258		}
259		lower := sb.String()
260	
261		if id, ok := knownAgents[lower]; ok {
262			return id
263		}
264	
265		for _, suffix := range []string{"code", "cli"} {
266			if len(lower) > len(suffix) && lower[len(lower)-len(suffix):] == suffix {
267				if id, ok := knownAgents[lower[:len(lower)-len(suffix)]]; ok {
268					return id
269				}
270			}
271		}
272	
273		if strings.HasPrefix(lower, "factoryaidroid") {
274			return "droid"
275		}
276	
277		return agentUnknown
278	}
279	
280	// parseFlexibleTime tries RFC3339, then RFC3339Nano.
281	func parseFlexibleTime(s string) (time.Time, error) {
282		t, err := time.Parse(time.RFC3339, s)
283		if err != nil {
284			t, err = time.Parse(time.RFC3339Nano, s)
285			if err != nil {
286				return time.Time{}, fmt.Errorf("parse time %q: %w", s, err)
287			}
288		}
289		return t, nil
290	}
